"""Versioned vendor records translated into a small, immutable internal model."""
from collections.abc import Callable, Iterable, Mapping
from dataclasses import dataclass


class AdapterError(ValueError):
    """An external record cannot be translated into a Lead."""


class IntegrationError(RuntimeError):
    """The injected vendor reader failed before records could be adapted."""


def normalized_email(value: object) -> str:
    if not isinstance(value, str):
        raise TypeError("email must be text")
    email = value.strip().lower()
    if (email.count("@") != 1 or any(c.isspace() for c in email)
            or not all(email.split("@"))):
        raise ValueError("email requires nonempty local and domain parts")
    return email


def score_value(value: object, *, csv: bool = False) -> int:
    if csv and isinstance(value, str):
        clean = value.strip()
        if not clean or any(c not in "0123456789" for c in clean):
            raise ValueError("CSV score must contain decimal digits")
        value = int(clean)
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError("score must be an integer")
    if not 0 <= value <= 10:
        raise ValueError("score must be between zero and ten")
    return value


@dataclass(frozen=True)
class Lead:
    email: str
    source: str
    score: int

    def __post_init__(self) -> None:
        object.__setattr__(self, "email", normalized_email(self.email))
        if not isinstance(self.source, str) or not self.source.strip():
            raise ValueError("source must be nonblank text")
        score_value(self.score)


def record(value: object) -> Mapping[str, object]:
    if not isinstance(value, Mapping):
        raise TypeError("record must be a mapping")
    if any(not isinstance(k, str) for k in value):
        raise TypeError("record keys must be text")
    return value


def version(value: Mapping[str, object], *, csv: bool = False) -> int:
    raw = value.get("version", 1)
    if csv and raw in ("1", "2"):
        raw = int(str(raw))
    if type(raw) is not int:
        raise TypeError("version must be an integer")
    if raw not in (1, 2):
        raise ValueError("unsupported record version")
    return raw


def adapt_csv_row(row: Mapping[str, object]) -> Lead:
    try:
        source = record(row)
        v = version(source, csv=True)
        email_key, score_key = ("email_address", "score") if v == 1 else ("contact_email", "lead_score")
        return Lead(normalized_email(source[email_key]), "csv",
                    score_value(source.get(score_key, 0), csv=True))
    except (KeyError, TypeError, ValueError) as error:
        raise AdapterError("invalid CSV lead") from error


def adapt_webhook(payload: Mapping[str, object]) -> Lead:
    try:
        source = record(payload)
        if version(source) == 1:
            email, score = source["userEmail"], source.get("priority", 0)
        else:
            contact = record(source["contact"])
            ranking = record(source.get("ranking", {}))
            email, score = contact["email"], ranking.get("score", 0)
        return Lead(normalized_email(email), "webhook", score_value(score))
    except (KeyError, TypeError, ValueError) as error:
        raise AdapterError("invalid webhook lead") from error


def flag_high_score(lead: Lead) -> Lead:
    if not isinstance(lead, Lead):
        raise TypeError("transform requires a Lead")
    return Lead(lead.email, lead.source, 10) if lead.score >= 8 else lead


def mapped_lead(raw: Mapping[str, object],
                adapter: Callable[[Mapping[str, object]], Lead],
                transform: Callable[[Lead], Lead]) -> Lead:
    lead = adapter(raw)
    if not isinstance(lead, Lead):
        raise TypeError("adapter must return a Lead")
    result = transform(lead)
    if not isinstance(result, Lead):
        raise TypeError("transform must return a Lead")
    return result


def run_pipeline(records: Iterable[Mapping[str, object]],
                 adapter: Callable[[Mapping[str, object]], Lead],
                 transform: Callable[[Lead], Lead]) -> list[Lead]:
    if not callable(adapter) or not callable(transform):
        raise TypeError("adapter and transform must be callable")
    return [mapped_lead(raw, adapter, transform) for raw in records]


class LeadImportTemplate:
    source_name = "unknown"

    def adapt(self, value: Mapping[str, object]) -> Lead:
        raise NotImplementedError("choose an external record adapter")

    def transform(self, lead: Lead) -> Lead:
        return flag_high_score(lead)

    def run(self, records: Iterable[Mapping[str, object]]) -> list[Lead]:
        return run_pipeline(records, self.adapt, self.transform)


class CsvLeadImporter(LeadImportTemplate):
    source_name = "csv"
    def adapt(self, value: Mapping[str, object]) -> Lead:
        return adapt_csv_row(value)


class WebhookLeadImporter(LeadImportTemplate):
    source_name = "webhook"
    def adapt(self, value: Mapping[str, object]) -> Lead:
        return adapt_webhook(value)


def fetch_leads(fetch: Callable[[], Iterable[Mapping[str, object]]],
                adapter: Callable[[Mapping[str, object]], Lead],
                transform: Callable[[Lead], Lead] = flag_high_score) -> list[Lead]:
    try:
        # Materialize here so iteration-time I/O failures retain the same boundary.
        rows = tuple(fetch())
    except OSError as error:
        raise IntegrationError("vendor lead reader failed") from error
    return run_pipeline(rows, adapter, transform)


def build_csv_records() -> list[dict[str, object]]:
    return [{"email_address": "ADA@example.com", "score": "7"},
            {"email_address": "TURING@example.com", "score": "9"}]


def build_webhook_records() -> list[dict[str, object]]:
    return [{"userEmail": "hopper@example.com", "priority": 8}]


def main() -> None:
    csv_rows, webhook_rows = build_csv_records(), build_webhook_records()
    print("csv:", CsvLeadImporter().run(csv_rows))
    print("webhook:", WebhookLeadImporter().run(webhook_rows))
    print("functional equal:", run_pipeline(csv_rows, adapt_csv_row, flag_high_score)
          == CsvLeadImporter().run(csv_rows))


if __name__ == "__main__":
    main()

"""PDP9 compares extension forms without changing the PDP8 adapter schema."""
from main import (CsvLeadImporter, WebhookLeadImporter, Lead, adapt_csv_row,
                  adapt_webhook, build_csv_records, build_webhook_records,
                  flag_high_score, run_pipeline)


def keep_score(lead: Lead) -> Lead:
    return lead


class KeepCsvScore(CsvLeadImporter):
    def transform(self, lead: Lead) -> Lead:
        return keep_score(lead)


def comparison_main() -> None:
    csv_rows = build_csv_records()
    webhook_rows = build_webhook_records()
    print("csv forms equal:", CsvLeadImporter().run(csv_rows)
          == run_pipeline(csv_rows, adapt_csv_row, flag_high_score))
    print("webhook forms equal:", WebhookLeadImporter().run(webhook_rows)
          == run_pipeline(webhook_rows, adapt_webhook, flag_high_score))
    functional = run_pipeline(csv_rows, adapt_csv_row, keep_score)
    print("replacement scores:", [lead.score for lead in functional])
    print("replacement equal:", functional == KeepCsvScore().run(csv_rows))


if __name__ == "__main__":
    comparison_main()

"""PDP9 exposes ordered short-circuit behavior through both extension forms."""
from collections.abc import Mapping
from main import Lead, LeadImportTemplate, adapt_csv_row, run_pipeline


def failure_main() -> None:
    rows: list[dict[str, object]] = [
        {"email_address": "first@example.com"},
        {"email_address": "second@example.com"},
        {"email_address": "third@example.com"},
    ]
    for form in ("class", "callable"):
        events: list[str] = []
        failure = RuntimeError("second transform")

        def adapt(row: Mapping[str, object]) -> Lead:
            value = adapt_csv_row(row)
            events.append("adapt:" + value.email.split("@")[0])
            return value

        def transform(value: Lead) -> Lead:
            name = value.email.split("@")[0]
            events.append("transform:" + name)
            if name == "second":
                raise failure
            return value

        class TracedImporter(LeadImportTemplate):
            def adapt(self, row: Mapping[str, object]) -> Lead:
                return adapt(row)

            def transform(self, value: Lead) -> Lead:
                return transform(value)

        try:
            if form == "class":
                TracedImporter().run(rows)
            else:
                run_pipeline(rows, adapt, transform)
        except RuntimeError as error:
            print(form + " same failure:", error is failure)
            print(form + " events:", events)


if __name__ == "__main__":
    failure_main()

from dataclasses import FrozenInstanceError
import unittest
from main import (AdapterError, CsvLeadImporter, IntegrationError, Lead,
    LeadImportTemplate, WebhookLeadImporter, adapt_csv_row, adapt_webhook,
    fetch_leads, flag_high_score, run_pipeline)


class AdapterContracts(unittest.TestCase):
    def test_csv_versions_minimal_defaults_and_unknown_fields(self):
        self.assertEqual(adapt_csv_row({"email_address":" ADA@example.com ","score":" 7 ","extra":None}),Lead("ada@example.com","csv",7))
        self.assertEqual(adapt_csv_row({"version":"2","contact_email":"ADA@example.com","lead_score":"10"}),Lead("ada@example.com","csv",10))
        self.assertEqual(adapt_csv_row({"email_address":"a@b"}).score,0)

    def test_webhook_versions_and_nested_default_policy(self):
        self.assertEqual(adapt_webhook({"userEmail":" A@B ","priority":8}),Lead("a@b","webhook",8))
        self.assertEqual(adapt_webhook({"version":2,"contact":{"email":"A@B"},"ranking":{"score":9}}).score,9)
        self.assertEqual(adapt_webhook({"version":2,"contact":{"email":"A@B"}}).score,0)
        self.assertEqual(adapt_webhook({"userEmail":"a@b"}).score,0)

    def test_malformed_and_unknown_version_records_keep_validation_causes(self):
        for adapt,values in [(adapt_csv_row,[{}, {"version":3}, {"version":True}, {"email_address":None}, {"email_address":"a@b","score":"7.5"}]),(adapt_webhook,[{}, {"version":2,"contact":[]}, {"version":2,"contact":{"email":"a@b"},"ranking":None}, {"version":"1","userEmail":"a@b"}])]:
            for value in values:
                with self.subTest(value=value), self.assertRaises(AdapterError) as caught: adapt(value)
                self.assertIsInstance(caught.exception.__cause__,(KeyError,TypeError,ValueError))

    def test_scores_emails_and_internal_records_are_validated(self):
        for value in [True,1.5,"3",None,-1,11]:
            with self.assertRaises(AdapterError): adapt_webhook({"userEmail":"a@b","priority":value})
        for email in ["", "missing", "a@@b", "@b", "a@", "a @b"]:
            with self.assertRaises(AdapterError): adapt_csv_row({"email_address":email})
        with self.assertRaises(TypeError): Lead("a@b","csv",True)

    def test_models_and_inputs_do_not_share_mutable_vendor_state(self):
        raw={"version":2,"contact":{"email":"A@B"},"ranking":{"score":4}}
        value=adapt_webhook(raw); raw["contact"]["email"]="changed@x"
        self.assertEqual(value,Lead("a@b","webhook",4))
        with self.assertRaises(FrozenInstanceError): value.score=9

    def test_pipeline_and_template_preserve_order_and_equal_behavior(self):
        raw=[{"email_address":"B@X","score":"9"},{"email_address":"A@X","score":"7"}]
        expected=[Lead("b@x","csv",10),Lead("a@x","csv",7)]
        self.assertEqual(CsvLeadImporter().run(iter(raw)),expected)
        self.assertEqual(run_pipeline(iter(raw),adapt_csv_row,flag_high_score),expected)
        self.assertEqual(WebhookLeadImporter().run([{"userEmail":"a@x","priority":8}]),[Lead("a@x","webhook",10)])
        self.assertEqual(run_pipeline([],adapt_csv_row,flag_high_score),[])

    def test_pipeline_stops_at_first_failure_and_preserves_callback_identity(self):
        error=LookupError("transform"); calls=[]
        def transform(lead): calls.append(lead.email); raise error
        rows=[{"email_address":"a@x"},{"email_address":"b@x"}]
        with self.assertRaises(LookupError) as caught: run_pipeline(rows,adapt_csv_row,transform)
        self.assertIs(caught.exception,error); self.assertEqual(calls,["a@x"])

    def test_pipeline_validates_callable_and_return_contracts(self):
        with self.assertRaises(TypeError): run_pipeline([],None,flag_high_score)
        with self.assertRaises(TypeError): run_pipeline([{}],lambda row:{},flag_high_score)
        with self.assertRaises(TypeError): run_pipeline([{"email_address":"a@b"}],adapt_csv_row,lambda lead:None)
        with self.assertRaises(NotImplementedError): LeadImportTemplate().adapt({})

    def test_fetch_boundary_maps_call_and_iteration_io_failures_only(self):
        error=TimeoutError("vendor")
        def failed(): raise error
        def interrupted():
            yield {"email_address":"a@b"}
            raise error
        for fetch in [failed,interrupted]:
            with self.assertRaises(IntegrationError) as caught: fetch_leads(fetch,adapt_csv_row)
            self.assertIs(caught.exception.__cause__,error)
        bug=LookupError("programming")
        def broken(): raise bug
        with self.assertRaises(LookupError) as caught: fetch_leads(broken,adapt_csv_row)
        self.assertIs(caught.exception,bug)

    def test_threshold_and_injected_pipeline_comparison(self):
        for score,expected in [(0,0),(7,7),(8,10),(9,10),(10,10)]:
            value=Lead("a@b","manual",score)
            self.assertEqual(flag_high_score(value).score,expected)
            self.assertEqual(value.score,score)
        rows=[{"version":2,"contact":{"email":"A@B"},"ranking":{"score":9}}]
        self.assertEqual(fetch_leads(lambda:rows,adapt_webhook,lambda lead:lead),[Lead("a@b","webhook",9)])


if __name__=="__main__": unittest.main()

